<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { requestVisitReport } from '../../api/cc-visit-report';
import { indiaStamp, visitStatus } from '../../lib/cc';
import { businessCycle,cycleDays } from '../../lib/cc-visit-report';
const props=defineProps({branch:String,agent:String,refreshKey:Number});const emit=defineEmits(['select']);
const anchor=indiaStamp().slice(0,10),offset=ref(0),rows=ref([]),busy=ref(false),error=ref(''),partial=ref(false);let generation=0,controller,previousRefresh;
const minOffset=computed(()=>-((Number(anchor.slice(0,4))-2025)*12+Number(anchor.slice(5,7))-1-(Number(anchor.slice(8))<6?1:0)));
const totals=computed(()=>Object.values(counts.value).reduce((a,r)=>({appointments:a.appointments+r.appointments,visits:a.visits+r.visits,booked:a.booked+r.booked}),{appointments:0,visits:0,booked:0}));
const days=computed(()=>cycleDays(anchor,offset.value)),range=computed(()=>businessCycle(anchor,offset.value));
const counts=computed(()=>{const output={};for(const row of rows.value){if(props.branch&&(row.branch||row.lead_assign_to_branch)!==props.branch||props.agent&&row.lead_owner!==props.agent)continue;const key=String(row.day||row.custom_appointment_date_and_time).slice(0,10);const item=output[key]||={appointments:0,visits:0,booked:0};const count=Number(row.count??1);item.appointments+=count;if(visitStatus(row).startsWith('Visited'))item.visits+=count;if(visitStatus(row)==='Visited-BKD')item.booked+=count;}return output;});
async function load(){const refresh=previousRefresh!==undefined&&previousRefresh!==props.refreshKey;previousRefresh=props.refreshKey;const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';rows.value=[];try{const data=await requestVisitReport({view:'calendar',from_date:range.value[0],to_date:range.value[1]},controller.signal,refresh);if(token!==generation)return;rows.value=data.days||[];partial.value=!!data.truncated;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch(()=>[offset.value,props.refreshKey],load,{immediate:true});onBeforeUnmount(()=>{generation++;controller?.abort();});
</script>
<template><section class="cc-month-strip lr5-cal" aria-label="Daily appointment strip"><button class="ar" :disabled="busy||offset<=minOffset" aria-label="Previous business month" @click="offset--">‹</button><div class="cc-month-scroll"><table :aria-busy="busy"><thead><tr><th scope="col" class="lb"><b>{{range[0]}}<br>{{range[1]}}</b></th><th v-for="day in days" :key="day" scope="col" :class="{today:day===anchor,sunday:new Date(day+'T12:00:00Z').getUTCDay()===0,monthstart:day.endsWith('-01')}"><button :aria-label="'Show appointments for '+day" @click="emit('select',day)">{{Number(day.slice(8))}}<small>{{new Date(day+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',timeZone:'Asia/Kolkata'})}}</small></button></th></tr></thead><tbody><tr><th scope="row" class="lb">Appointments <b>{{totals.appointments}}</b></th><td v-for="day in days" :key="day" class="ap" :class="{monthstart:day.endsWith('-01')}">{{busy?'…':counts[day]?.appointments||'·'}}</td></tr><tr><th scope="row" class="lb">V / B <b>{{totals.visits}} / {{totals.booked}}</b></th><td v-for="day in days" :key="day" class="vb" :class="{monthstart:day.endsWith('-01')}">{{busy?'…':counts[day]?.visits||0}} / <b>{{busy?'…':counts[day]?.booked||0}}</b></td></tr></tbody></table><p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="partial" role="alert">Partial calendar totals. Narrow the report dates.</p></div><button class="ar" :disabled="busy||offset>=1" aria-label="Next business month" @click="offset++">›</button></section></template>
<style scoped>
.cc-month-strip{display:flex;align-items:stretch;border:1px solid #c9a24b;border-radius:12px;background:#fffdf7;margin:0 0 10px;overflow:hidden;color:#16402d;font:11px/1.2 Poppins,sans-serif;box-shadow:0 1px 4px #1f6b4519}
.cc-month-strip>.ar{flex:0 0 22px;min-width:22px;min-height:0;padding:0;border:0;border-radius:0;background:linear-gradient(180deg,#1f6b45,#0f3524);color:#fff;font-size:15px;font-weight:800;cursor:pointer}
.cc-month-strip>.ar:disabled{background:#e9efe9;color:#b9c4bc;cursor:default}.cc-month-scroll{flex:1;min-width:0;overflow-x:auto}.cc-month-strip table{border-collapse:collapse;width:100%;table-layout:fixed;min-width:620px;font-size:10px}.cc-month-strip :is(th,td){text-align:center;padding:3.5px 0;border-left:1px solid #a0965047;white-space:nowrap;overflow:hidden;min-width:0;line-height:1.2}.cc-month-strip .lb{width:92px;text-align:left;padding-left:6px;font-size:10px;border-left:0;color:#5d6f66}.cc-month-strip .lb b{font-size:10px;color:#16402d}.cc-month-strip th{background:#f7f1df}.cc-month-strip th button{display:block;width:100%;min-width:0;min-height:0;border:0;border-radius:0;background:transparent;color:inherit;padding:0;font:inherit;cursor:pointer;line-height:1.2}.cc-month-strip small{display:block;font-size:8.5px;color:#8a7a4e}.cc-month-strip .today{background:#c9a24b;color:#fff}.cc-month-strip .today small{color:inherit}.cc-month-strip .sunday{background:#fff5f5}.cc-month-strip .monthstart{border-left:2px solid #c9a24b}.cc-month-strip .ap{font-weight:800}.cc-month-strip .vb{font-size:9.5px;color:#1766ad}.cc-month-strip .vb b{color:#15803d}.cc-month-strip p{padding:3px 6px;margin:0}
</style>
